using Microsoft.EntityFrameworkCore;
class BlogContext : DbContext
{
    public DbSet<Blog> Blogs => Set<Blog>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // Breaking change 1: Discriminator property renamed from "Discriminator" to "$type".
        // Preserve compat with existing documents that use "Discriminator".
        modelBuilder.Entity<Blog>().HasDiscriminator<string>("Discriminator");

        // Breaking change 2: Id format changed from "EntityType|Key" to just "Key" in EF 9.
        // Existing documents have ids like "Blog|1", so keep the old id factory.
        modelBuilder.Entity<Blog>().HasPartitionKey(b => b.Id);
        modelBuilder.Entity<Blog>().Property(b => b.Id)
            .ToJsonProperty("id")
            .HasValueGenerator<LegacyCosmosIdValueGenerator>();

        // Breaking change 3: Cosmos DB provider no longer supports sync I/O by default.
        // See SyncJob.cs for the async fix.

        // Breaking change 4: HasIndex is not supported on Cosmos DB (now throws instead of being ignored).
        // Removed: modelBuilder.Entity<Blog>().HasIndex(b => b.Name);
    }
}
class Blog { public string Id { get; set; } public string Name { get; set; }

    // Breaking change 5: Raw SQL queries like
    //   SELECT * FROM c WHERE c.Discriminator = 'Blog'
    // must be updated to:
    //   SELECT * FROM c WHERE c.Discriminator = 'Blog'   (still works IF you configure
    //   HasDiscriminator("Discriminator") above, otherwise change to c["$type"] = 'Blog')
}

// Value generator that preserves the legacy "EntityType|Key" id format for existing documents.
using Microsoft.EntityFrameworkCore.ChangeTracking;
using Microsoft.EntityFrameworkCore.ValueGeneration;
class LegacyCosmosIdValueGenerator : ValueGenerator<string>
{
    public override bool GeneratesTemporaryValues => false;
    public override string Next(EntityEntry entry)
        => $"{entry.Metadata.ShortName()}|{Guid.NewGuid()}";
}

